command:
cd workspace/ && python3 - <<'EOF'
import pathlib
p=pathlib.Path('tools/build.py'); s=p.read_text()
i=s.index("        ref = next(system[i] for i in IDS if i in system)"); j=s.index("        nbars += len(bars); system = {}")
new='''        ref = next(system[i] for i in IDS if i in system)
        bars = bars_of(ref)
        FIELD = re.compile(r'\\[([MQ]):[^\\]]*\\]\\s*')
        def split(mus):
            parts = re.split(r'(\\|\\]|\\|)', mus); return parts[0::2], parts[1::2]
        # metre changes belong in every voice, tempo changes only on the top staff
        fm, fq = {}, {}
        for vid, mus in system.items():
            nb = bars_of(mus)
            if len(nb) != len(bars): raise SystemExit(f'{stem}: voice {vid} has {len(nb)} bars, system has {len(bars)} (near bar {nbars + 1}): {mus[:70]}')
            for k, seg in enumerate(split(mus)[0][:len(bars)]):
                for f in FIELD.finditer(seg): (fm if f.group(1) == 'M' else fq).setdefault(k, f.group(0).strip())
        for vid in IDS:
            if vid in system:
                segs, seps = split(system[vid])
            else:
                segs, seps = [' ' + rest(d) + ' ' for _, d, _ in bars] + [''], [b for _, _, b in bars]
            for k in range(len(bars)):
                body = FIELD.sub('', segs[k])
                pre = (fm.get(k, '') + ' ' if k in fm else '') + (fq.get(k, '') + ' ' if k in fq and vid == IDS[0] else '')
                segs[k] = (' ' if k else '') + pre + body.strip() + ' '
            mus = ''.join(a + b for a, b in zip(segs, seps + [''])).strip()
            t = TRIM.get(vid, 0)
            if t: mus = re.sub(r'!(pppp|ppp|pp|p|mp|mf|f|ff|fff)!', lambda m: '!' + LADDER[max(0, LADDER.index(m.group(1)) - t)] + '!', mus)
            if vid in STR or '@' in mus:
                mus = mus.replace('@pizz ', '[I:MIDI program 45] "pizz."').replace('@arco ', '[I:MIDI program %d] "arco"' % PROG[vid])
            out.append(f'[V:{vid}] {mus}')
'''
s=s[:i]+new+s[j:]
p.write_text(s)
EOF
