command:
cd workspace/ && python3 - <<'EOF'
import re,json
names=['fl','ob','cl','bn','hn','tp','tm','v1','v2','va','vc','cb']
rows={}
for l in open('logs/render-draft1.log'):
    m=re.match(r'movement (\d) \[(.*?)\]\s+(.*?)(\{.*\})',l)
    if not m:
        if 'console' in l or 'FAILED' in l or 'title' in l: print(l.strip()[:200])
        continue
    d=json.loads(m.group(4)); raw=d['rms']*d['rawPeak']/0.9
    key=m.group(2)
    if key=='all parts': print('mov',m.group(1),'all: sec',d['seconds'],'rawPeak',round(d['rawPeak'],3),'rawRMS',round(raw,4),'quiet',d['quietSeconds'][:8],'warn',d['warn'][:60], m.group(3))
    else: rows.setdefault(m.group(1),[]).append(round(raw,4))
for k,v in rows.items(): print('mov',k,' '.join(f'{n}:{x}' for n,x in zip(names,v)))
EOF

